# Design dimensions are assigned with co-prime strides to avoid local clustering.
def pick(seq,i,stride,offset=0): return seq[(i*stride+offset)%len(seq)]

def unique_section_sequence(i:int)->list[str]:
    rng=random.Random(9109+i*7919)
    pool=[x for x in SECTIONS if x not in {"services","proof"}]
    rng.shuffle(pool)
    n=5+(i%3)
    seq=["services","proof"]+pool[:n-2]
    rng.shuffle(seq)
    return seq

def cta_for(profile,conv):
    mapping={'book-appointment':'Book an appointment','request-quote':'Request a quote','call-now':'Call us','visit-location':'Plan your visit','reserve-table':'Reserve a table','start-trial':'Start free','submit-enquiry':'Send an enquiry','schedule-consultation':'Schedule a consultation','buy-product':'Shop the collection','register-course':'Register now','apply-now':'Apply now','view-portfolio':'View selected work','join-community':'Join the community','request-demo':'Request a demo'}
    if profile[0] in {'restaurant','cafe'}: return 'Reserve a table'
    if profile[0] in {'hotel','resort'}: return 'Check availability'
    return mapping[conv]

def _hex_luminance(value:str)->float:
    value=value.lstrip('#')
    rgb=[int(value[i:i+2],16)/255 for i in (0,2,4)]
    def lin(c): return c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4
    r,g,b=[lin(c) for c in rgb]
    return .2126*r+.7152*g+.0722*b

def _contrast(a:str,b:str)->float:
    x,y=_hex_luminance(a),_hex_luminance(b)
    return (max(x,y)+.05)/(min(x,y)+.05)

def palette_css(pal):
    bg,fg,a1,a2=pal
    primary_fg = '#050505' if _contrast(a1,'#050505') >= _contrast(a1,'#ffffff') else '#ffffff'
    return f'--bg:{bg};--fg:{fg};--primary:{a1};--primary-fg:{primary_fg};--secondary:{a2};--surface:color-mix(in srgb,var(--bg) 92%,var(--fg));--muted:color-mix(in srgb,var(--fg) 72%,var(--bg));--border:color-mix(in srgb,var(--fg) 22%,var(--bg))'

