def nav_markup(nav:str,business:str)->str:
    links='<a href="#services">Services</a><a href="#proof">Proof</a><a href="#contact">Contact</a>'
    if nav=='left-sidebar': return f'<aside className="navRail"><strong>{business}</strong><nav>{links}</nav></aside>'
    if nav=='vertical-rail': return f'<aside className="navRail vertical"><strong>{business}</strong><nav>{links}</nav></aside>'
    if nav=='centered-logo': return f'<header className="nav centered"><nav><a href="#services">Services</a></nav><strong>{business}</strong><nav><a href="#contact">Contact</a></nav></header>'
    if nav=='transparent-overlay': return f'<header className="nav overlay"><strong>{business}</strong><nav>{links}</nav></header>'
    if nav=='fullscreen-menu': return f'<header className="nav menu"><strong>{business}</strong><details><summary>Menu</summary><nav>{links}</nav></details></header>'
    if nav=='minimal-wordmark': return f'<header className="nav minimal"><strong>{business}</strong><a href="#contact">Contact</a></header>'
    if nav=='split-logo': return f'<header className="nav split"><nav><a href="#services">Services</a><a href="#proof">Proof</a></nav><strong>{business}</strong><a href="#contact">Contact</a></header>'
    if nav=='corner-dock': return f'<header className="nav dock"><strong>{business}</strong><nav>{links}</nav></header>'
    if nav=='statement-bar': return f'<header className="nav statement"><span>Independent / Local / Established</span><strong>{business}</strong><a href="#contact">Contact</a></header>'
    if nav=='editorial-index': return f'<header className="nav index"><strong>{business}</strong><span>Index 01—03</span><nav>{links}</nav></header>'
    if nav=='tabbed': return f'<header className="nav tabs"><strong>{business}</strong><nav>{links}</nav></header>'
    if nav=='lower-third': return f'<header className="nav lower"><strong>{business}</strong><nav>{links}</nav></header>'
    if nav=='mega-utility': return f'<header className="nav utility"><strong>{business}</strong><span>Open today</span><nav>{links}</nav></header>'
    if nav=='asymmetric-cluster': return f'<header className="nav cluster"><strong>{business}</strong><nav>{links}</nav><span>Est. 2026</span></header>'
    if nav=='compact-floating': return f'<header className="nav floating"><strong>{business}</strong><nav>{links}</nav></header>'
    return f'<header className="nav"><strong>{business}</strong><nav>{links}</nav></header>'

def hero_markup(hero:str,idx:int,profile,cta:str)->str:
    # Explicitly different markup families; no runtime generic renderer.
    visual='<div className="visual"><span className="visualIndex">%02d</span><div className="visualMark"/><small>{businessName}</small></div>'%(idx%100)
    image='{heroImage ? <img className="heroPhoto" src={heroImage} alt={imageAlt}/> : '+visual+'}'
    copy='<div className="heroCopy"><span className="eyebrow">{industryLabel}</span><h1>{headline}</h1><p className="lede">{description}</p><div className="heroActions"><a className="primary" href="#contact">'+cta+'</a><a href="#services">Explore</a></div></div>'
    if hero=='typography-only': return '<section className="hero typeOnly">'+copy+'<div className="oversizeWord">{businessName.slice(0,1)}</div></section>'
    if hero=='cinematic-fullscreen': return '<section className="hero cinematic">'+image+'<div className="shade"/>'+copy+'</section>'
    if hero=='split-image': return '<section className="hero splitHero">'+copy+image+'</section>'
    if hero=='asymmetric-editorial': return '<section className="hero asymHero"><div className="heroNumber">0'+str(idx%9+1)+'</div>'+copy+image+'</section>'
