    if hero=='floating-panels': return '<section className="hero floatingHero">'+copy+'<div className="floatStack">'+image+'<article>{services[0]}</article><article>{services[1]}</article></div></section>'
    if hero=='layered-photography': return '<section className="hero layeredHero"><div className="layered">'+image+'<div className="layerCard">{businessName}</div></div>'+copy+'</section>'
    if hero=='minimal-statement': return '<section className="hero minimalHero"><span className="eyebrow">{industryLabel}</span><h1>{headline}</h1><div className="minimalFoot"><p>{description}</p><a href="#contact">'+cta+'</a></div></section>'
    if hero=='navigation-led': return '<section className="hero navLedHero"><div className="navLedIndex"><a href="#services">Services</a><a href="#proof">Approach</a><a href="#contact">Contact</a></div>'+copy+'</section>'
