    if hero=='service-led': return '<section className="hero serviceHero"><div className="serviceHeroList">{services.slice(0,4).map((s,i)=><span key={s}>{String(i+1).padStart(2,"0")} — {s}</span>)}</div>'+copy+'</section>'
    if hero=='location-led': return '<section className="hero locationHero"><div className="mapPanel"><span>{address || "Local / Independent"}</span><div className="mapDot"/></div>'+copy+'</section>'
    if hero=='product-led': return '<section className="hero productLedHero">'+image+'<div className="productTitle">'+copy+'</div></section>'
    if hero=='archival-grid': return '<section className="hero archiveHero"><div className="archiveGrid"><span>Archive</span><span>{industryLabel}</span><span>Selected</span><span>2026</span></div>'+copy+'</section>'
    if hero=='circular-focus': return '<section className="hero circleHero"><div className="circleFrame">'+image+'</div>'+copy+'</section>'
    if hero=='diagonal-cut': return '<section className="hero diagonalHero">'+copy+'<div className="diagonalVisual">'+image+'</div></section>'
    if hero=='monumental-type': return '<section className="hero monumentalHero"><h1>{businessName}</h1><div className="monumentalBody"><p>{headline}</p><a href="#contact">'+cta+'</a></div></section>'
